<script setup>
import { computed, ref } from 'vue'
import { onLoad } from '@dcloudio/uni-app'
import { request } from '../../services/api'
const services=ref([]), barbers=ref([]), slots=ref([]), bookings=ref([]), serviceId=ref(1), barberId=ref(1), date=ref(''), time=ref('10:00'), customer=ref(''), phone=ref(''), loading=ref(true), message=ref('')
const selectedService=computed(()=>services.value.find(x=>x.id===serviceId.value)||services.value[0]), selectedBarber=computed(()=>barbers.value.find(x=>x.id===barberId.value)||barbers.value[0]), visibleSlots=computed(()=>slots.value.slice(0,6))
const tomorrow=()=>{const d=new Date(Date.now()+86400000);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
async function load(){loading.value=true;date.value=tomorrow();try{services.value=await request('/api/services');barbers.value=await request('/api/barbers');await loadSlots();if(phone.value)bookings.value=await request(`/api/bookings?phone=${phone.value}`)}catch(e){message.value=e.message||'服务暂不可用'}finally{loading.value=false}}
async function loadSlots(){try{const data=await request(`/api/slots?barberId=${barberId.value}&date=${date.value}`);slots.value=data.available;if(!slots.value.includes(time.value))time.value=slots.value[0]||''}catch(e){message.value=e.message}}
async function book(){message.value='';try{if(!customer.value||!/^1\d{10}$/.test(phone.value))throw Error('请输入姓名和 11 位手机号');const result=await request('/api/bookings','POST',{serviceId:serviceId.value,barberId:barberId.value,date:date.value,time:time.value,customer:customer.value,phone:phone.value});bookings.value=[result,...bookings.value];message.value='预约成功，店员将按时为你服务';uni.showToast({title:'预约成功',icon:'success'})}catch(e){message.value=e.message||'预约失败'}}
async function cancel(id){try{await request(`/api/bookings/${id}/cancel?phone=${phone.value}`,'POST');bookings.value=await request(`/api/bookings?phone=${phone.value}`);message.value='预约已取消'}catch(e){message.value=e.message}}
onLoad(load)
</script>
<template>
<view class="page">
  <view class="nav"><view><text class="brand">LUNE</text><text class="nav-sub">HAIR STUDIO</text></view><view class="nav-action">门店详情 <text>›</text></view></view>
  <view class="hero-card"><view class="hero-copy"><text class="eyebrow">DESIGN YOUR DAY</text><text class="title">今天，换个更好的自己</text><text class="subtitle">提前预约 · 到店免排队 · 专业设计师</text><view class="hero-meta"><text>营业 10:00—20:00</text><text>距你 1.2km</text></view></view><view class="hero-orb"><text>✦</text></view></view>
  <view v-if="loading" class="empty">正在加载服务...</view>
  <view v-else>
    <view class="section"><view class="section-head"><view><text class="section-title">精选服务</text><text class="section-desc">本周人气推荐</text></view><text class="section-link">全部服务 ›</text></view><scroll-view scroll-x class="service-scroll"><view v-for="s in services" :key="s.id" class="service-card" :class="{active:serviceId===s.id}" @click="serviceId=s.id"><view class="service-top"><text class="service-icon">{{s.icon}}</text><text v-if="s.id===1" class="hot">HOT</text></view><text class="service-name">{{s.name}}</text><text class="service-desc">{{s.desc}}</text><view class="service-foot"><text class="service-price">¥{{s.price}}</text><text class="minutes">{{s.minutes}} min</text></view></view></scroll-view></view>
    <view class="section"><view class="section-head"><view><text class="section-title">选择设计师</text><text class="section-desc">专业审美，细节到位</text></view><text class="section-link">3 位设计师</text></view><scroll-view scroll-x class="barber-scroll"><view v-for="b in barbers" :key="b.id" class="barber-card" :class="{active:barberId===b.id}" @click="barberId=b.id;loadSlots()"><view class="avatar">{{b.avatar}}</view><view class="barber-copy"><text class="barber-name">{{b.name}}</text><text class="barber-level">{{b.level}}</text><text class="barber-specialty">{{b.specialty}}</text></view><text class="check">{{barberId===b.id?'✓':'＋'}}</text></view></scroll-view></view>
    <view class="section booking-card"><view class="booking-title"><view><text class="section-title">预约时间</text><text class="section-desc">未来 14 天可预约</text></view><text class="calendar">▣</text></view><picker mode="date" :value="date" :start="tomorrow()" @change="e=>{date=e.detail.value;loadSlots()}"><view class="date-row"><view><text class="date-label">到店日期</text><text class="date-value">{{date}}</text></view><text class="arrow">›</text></view></picker><view class="slot-title"><text>可选时段</text><text>{{selectedBarber?.name}} · {{selectedService?.minutes||0}} 分钟</text></view><view class="slots"><text v-for="s in visibleSlots" :key="s" class="slot" :class="{active:time===s}" @click="time=s">{{s}}</text></view><view class="input-row"><input v-model="customer" placeholder="你的姓名"/><input v-model="phone" type="number" maxlength="11" placeholder="手机号"/></view><button class="primary" @click="book">确认预约 <text>¥{{selectedService?.price||0}}</text></button></view>
    <view class="section"><view class="section-head"><view><text class="section-title">我的预约</text><text class="section-desc">输入手机号后自动展示</text></view><text class="section-link">预约记录</text></view><view v-if="bookings.length" class="booking-item" v-for="b in bookings" :key="b.id"><view><text class="booking-name">{{b.serviceName}} · {{b.barberName}}</text><text class="booking-info">{{b.date}} {{b.time}} · ¥{{b.price}}</text></view><button class="small" v-if="b.status==='已预约'" @click="cancel(b.id)">取消</button><text v-else class="cancelled">{{b.status}}</text></view><view v-else class="empty-panel">填写手机号并预约，记录会出现在这里</view></view>
  </view>
  <view v-if="message" class="toast">{{message}}</view>
</view>
</template>
